launcher_validation.reproduction_script:
$tunnerActualRoot = $PWD.Path
$tunnerLauncher = Join-Path $tunnerActualRoot 'tools/dev/setup-r2.ps1'
$tunnerFixtureBase = [IO.Path]::GetFullPath((Join-Path $tunnerActualRoot 'artifacts/P1-024-RV001'))
$tunnerFixtureRoot = Join-Path $tunnerFixtureBase ('launcher-fixture-' + [Guid]::NewGuid().ToString('N'))
$global:tunnerLauncherFixture = [pscustomobject]@{ Root=$tunnerFixtureRoot; Code=0; Arguments=@(); Calls=0 }
function Import-Module { }
function Resolve-TunnerRepositoryRoot { $global:tunnerLauncherFixture.Root }
function dotnet {
 $global:tunnerLauncherFixture.Arguments = @($args)
 $global:tunnerLauncherFixture.Calls++
 $global:LASTEXITCODE = $global:tunnerLauncherFixture.Code
}
try {
 [void][IO.Directory]::CreateDirectory((Join-Path $tunnerFixtureRoot 'local-config/r2'))
 $tunnerFixtureTemplate = Join-Path $tunnerFixtureRoot 'local-config/r2/profile.example.json'
 [IO.File]::Copy((Join-Path $tunnerActualRoot 'local-config/r2/profile.example.json'),$tunnerFixtureTemplate,$false)
 $tunnerExpected = [IO.File]::ReadAllText($tunnerFixtureTemplate)
 & $tunnerLauncher
 $tunnerDefaultProfile = [IO.Path]::GetFullPath((Join-Path $tunnerFixtureRoot 'local-config/r2/profile.json'))
 if ([IO.File]::ReadAllText($tunnerDefaultProfile) -ne $tunnerExpected -or $global:tunnerLauncherFixture.Arguments -notcontains 'local-r2' -or $global:tunnerLauncherFixture.Arguments[-1] -ne $tunnerDefaultProfile) { throw 'First-run copy or invocation failed.' }
 [IO.File]::WriteAllText($tunnerDefaultProfile,'preserve-existing-profile-bytes')
 & $tunnerLauncher
 if ([IO.File]::ReadAllText($tunnerDefaultProfile) -ne 'preserve-existing-profile-bytes') { throw 'Existing profile was overwritten.' }
 $tunnerAlternate = [IO.Path]::GetFullPath((Join-Path $tunnerFixtureRoot 'local-config/r2/path with spaces/profile.json'))
 & $tunnerLauncher -ProfilePath $tunnerAlternate
 if ([IO.File]::ReadAllText($tunnerAlternate) -ne $tunnerExpected -or $global:tunnerLauncherFixture.Arguments[-1] -ne $tunnerAlternate) { throw 'Alternate profile path handling failed.' }
 $global:tunnerLauncherFixture.Code = 7
 $tunnerFailedAsExpected = $false
 try { & $tunnerLauncher } catch { $tunnerFailedAsExpected = $_.Exception.Message.StartsWith('Local R2 setup/validation failed.') }
 if (-not $tunnerFailedAsExpected -or $global:tunnerLauncherFixture.Calls -ne 4) { throw 'Child failure did not propagate.' }
 Write-Output ('Launcher production-script scenarios: PASS 4/4; PowerShell ' + $PSVersionTable.PSVersion.ToString() + '; dotnet stubbed, no credentials or provider calls.')
}
finally {
 Set-Location -LiteralPath $tunnerActualRoot
 $tunnerFixtureResolved = [IO.Path]::GetFullPath($tunnerFixtureRoot)
 if (-not $tunnerFixtureResolved.StartsWith($tunnerFixtureBase + [IO.Path]::DirectorySeparatorChar,[StringComparison]::OrdinalIgnoreCase)) { throw 'Fixture cleanup outside intended artifact directory.' }
 if (Test-Path -LiteralPath $tunnerFixtureResolved) { Remove-Item -LiteralPath $tunnerFixtureResolved -Recurse -Force }
 Remove-Variable tunnerLauncherFixture -Scope Global -ErrorAction SilentlyContinue
}
